with unpacked as (select id, plan, effective_from, currency, tier_limits, tier_prices, slice(tier_limits, 1, 2) as first_two_limits, array_min(tier_prices) as lowest_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices from price_tiers) select id, plan, currency, cume_dist() over (order by lowest_price nulls last) as lowest_price_cume_dist, lag(lowest_price, 1) over (partition by plan order by lowest_price, id) as prev_lowest_price, rank() over (partition by currency order by lowest_price desc) as lowest_price_rank from unpacked where plan in ('enterprise', 'starter', 'pro');
